import heapq

def k_largest(A, k):
    heap = []                     # min-heap of the best k so far
    for x in A:
        heapq.heappush(heap, x)
        if len(heap) > k:
            heapq.heappop(heap)   # drop the smallest of the k + 1
    return sorted(heap, reverse=True)

print(k_largest([5, 1, 9, 3, 7], 2))  # -> [9, 7]
